    feedbackUrl: env.DELPHI_FEEDBACK_URL || "https://feedback.delphi.fyi/v1/feedback",
    firecrawlUrl: env.FIRECRAWL_BASE_URL || "https://api.firecrawl.dev/v1",
  };
}
